use browser_control_sdk::Client;use serde_json::json;
fn main(){let endpoint=std::env::args().nth(1).unwrap();let mut c=Client::new().unwrap();c.call("connect",json!({"endpoint":endpoint})).unwrap();let result=c.call("request",json!({"method":"fixture.echo","params":{"text":"café"}})).unwrap();assert_eq!(result["parameters"]["text"],"café");assert_eq!(c.call("request",json!({"method":"fixture.uint64"})).unwrap(),"18446744073709551615");for method in ["fixture.error","fixture.bad_id","fixture.oversize"]{assert!(c.call("request",json!({"method":method})).is_err());}assert!(c.call("request",json!({"method":"fixture.error"})).unwrap_err().message.contains("test_error"));let before=c.call("request",json!({"method":"fixture.count"})).unwrap().as_u64().unwrap();assert!(c.call("request",json!({"method":"fixture.drop"})).is_err());assert_eq!(c.call("request",json!({"method":"fixture.count"})).unwrap().as_u64().unwrap(),before+1);assert!(c.call("request",json!({"method":"fixture.hang","timeout":5})).is_err());c.close().unwrap();}
